/// Preserve the pre-hardening ordinary-data behavior by materializing it as
/// explicit, auditable collection grants. The sync hooks themselves remain
/// fail-closed and consult only native policy plus these exact grants.
pub(super) fn ensure_legacy_collection_grants(
    root: &Path,
    collections: &[String],
) -> anyhow::Result<()> {
    // Loading local module mappings may hash app assets. Resolve ownership
    // once before opening the SQLite write transaction to avoid startup lock
    // contention during capability issuance.
    let server_owned_collections =
        super::external_sql_sync::server_owned_projection_collections(root)?;
    let mut conn = open_store(root)?;
    let tx = conn.transaction()?;
    let now = now_ms() as i64;
    for collection in collections {
        let collection = collection.trim();
        if collection.is_empty()
            || policy::ADMIN_ONLY_COLLECTIONS.contains(&collection)
            || collection == "ctox_queue_tasks"
            || policy::is_cockpit_projection(collection)
        {
            continue;
        }
        let server_owned_write = super::threads::is_threads_owned_collection(collection)
            || server_owned_collections.contains(collection);
        if server_owned_write {
            tx.execute(
                "UPDATE business_permission_grants
                 SET active=0,
                     reason='Server-owned collection is read-only for browser sync',
                     updated_at_ms=?1
                 WHERE active=1
                   AND permission=?2
                   AND scope_type='collection'
                   AND scope_id=?3
                   AND created_by='business-os-policy-migration'",
                params![now, BusinessOsPermission::DataWrite.as_str(), collection],
            )?;
        }
        for role in ["founder", "user"] {
            for permission in [
                BusinessOsPermission::DataRead,
                BusinessOsPermission::DataWrite,
            ] {
                if permission == BusinessOsPermission::DataWrite && server_owned_write {
                    continue;
                }
                let grant_id = format!(
                    "migration.sync.{}.{}.{}",
                    role,
                    permission.as_str().replace('.', "_"),
                    collection
                );
                tx.execute(
                    "INSERT OR IGNORE INTO business_permission_grants
                        (grant_id, subject_type, subject_id, permission, scope_type, scope_id,
                         active, reason, created_by, created_at_ms, updated_at_ms)
                     VALUES (?1, 'role', ?2, ?3, 'collection', ?4, 1,
                             'Migrated legacy sync access to exact collection grant',
                             'business-os-policy-migration', ?5, ?5)",
                    params![grant_id, role, permission.as_str(), collection, now],
                )?;
            }
        }
    }
    tx.commit()?;
    Ok(())
}

fn business_os_collection_names_for_legacy_grants() -> Vec<String> {
    business_os_schema_contract_for_store()
        .keys()
        .cloned()
        .collect()
}

fn ensure_default_sync_collection_grants(root: &Path) -> anyhow::Result<()> {
    ensure_legacy_collection_grants(root, &business_os_collection_names_for_legacy_grants())
}

/// Whether server-authoritative per-collection sync authorization is enforced.
/// Default ON: the policy matrix is deny-by-exception for admin-only
/// collections, and browsers now carry native-signed capability tokens in the
/// WebRTC handshake. Operators can still opt out through typed runtime config
/// during legacy rollout, but absence of config must not leave sync fail-open.
pub fn collection_authz_enabled(root: &Path) -> bool {
    !matches!(
        crate::inference::runtime_env::env_or_config(root, "CTOX_BUSINESS_OS_COLLECTION_AUTHZ")
            .as_deref()
            .map(str::trim)
            .map(str::to_ascii_lowercase)
            .as_deref(),
        Some("0" | "false" | "off" | "no")
    )
}

/// Issue a capability token for an active Business OS user, binding their id to
/// their CURRENT server-side role. This is the native-authoritative step: a
/// browser obtains one of these after authenticating and then carries it on
/// every command so the native side can trust the role without trusting the
/// browser-asserted actor. Returns `(token, expires_at_ms)`.
pub fn issue_business_os_capability_token(
    root: &Path,
    user_id: &str,
    now_ms: i64,
) -> anyhow::Result<(String, i64)> {
    issue_business_os_capability_token_until(
        root,
        user_id,
        now_ms,
        now_ms + CAPABILITY_TOKEN_TTL_MS,
    )
}

fn issue_business_os_capability_token_until(
    root: &Path,
    user_id: &str,
    now_ms: i64,
    expires_at_ms: i64,
) -> anyhow::Result<(String, i64)> {
    issue_business_os_capability_token_until_with_binding(
        root,
        user_id,
        now_ms,
        expires_at_ms,
        None,
    )
}

fn issue_business_os_capability_token_until_with_binding(
    root: &Path,
    user_id: &str,
    now_ms: i64,
    expires_at_ms: i64,
    device_binding: Option<&super::capability::CapabilityDeviceBinding>,
) -> anyhow::Result<(String, i64)> {
    issue_business_os_capability_token_until_with_identity(
        root,
        user_id,
        None,
        now_ms,
        expires_at_ms,
        device_binding,
    )
}

fn issue_business_os_capability_token_until_with_identity(
    root: &Path,
    user_id: &str,
    email: Option<&str>,
    now_ms: i64,
    expires_at_ms: i64,
    device_binding: Option<&super::capability::CapabilityDeviceBinding>,
) -> anyhow::Result<(String, i64)> {
    anyhow::ensure!(
        expires_at_ms > now_ms,
        "capability expiry must be in the future"
    );
    anyhow::ensure!(
        expires_at_ms <= now_ms + CAPABILITY_TOKEN_TTL_MS,
        "capability expiry exceeds the native maximum"
    );
    // The browser resolves this token before the first WebRTC handshake. Ensure
    // deterministic baseline grants before reading capability_epoch; otherwise
    // native peer startup can insert grants moments later and invalidate the
    // freshly issued token before its first collection fetch.
    ensure_default_sync_collection_grants(root)?;
    let conn = open_store(root)?;
    seed_configured_business_users(&conn)?;
    let user = active_business_user(&conn, user_id.trim())?
        .ok_or_else(|| anyhow::anyhow!("no active Business OS user {user_id:?}"))?;
    let actor_epoch: i64 = conn.query_row(
        "SELECT capability_epoch FROM business_users WHERE user_id = ?1 AND active = 1",
        params![user.id.as_str()],
        |row| row.get(0),
    )?;
    let secret = capability_signing_secret(root)?;
    let token = super::capability::issue_capability_token_with_epoch_and_identity(
        &secret,
        &user.id,
        email,
        &normalize_business_role(&user.role),
        actor_epoch,
        now_ms,
        expires_at_ms,
        device_binding,
    );
    Ok((token, expires_at_ms))
}

/// Issue a capability token for the already authenticated HTTP session.
///
/// The Business OS shell can run from a local implicit desktop session without
/// an explicit login cookie. That session is still server-authenticated (the
/// server derived it from a loopback request and local runtime config), but the
/// normal "remember session user" path intentionally does not add implicit
/// local-dev to the team roster. A WebRTC capability token, however, needs a
/// durable active actor and capability epoch. Materialize exactly this
/// server-derived session actor here before delegating to the normal issuer.
pub fn issue_business_os_capability_token_for_session(
    root: &Path,
    session: &BusinessOsSession,
    now_ms: i64,
) -> anyhow::Result<(String, i64)> {
    anyhow::ensure!(session.authenticated, "authenticated session is required");
    let user = session
        .user
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("authenticated session has no user"))?;
    let user_id = user.id.trim();
    anyhow::ensure!(!user_id.is_empty(), "session user id is required");
    let display_name = user.display_name.trim();
    let display_name = if display_name.is_empty() {
        user_id
    } else {
        display_name
    };
    let role = normalize_business_role(&user.role);
    let conn = open_store(root)?;
    seed_configured_business_users(&conn)?;
    conn.execute(
        "INSERT INTO business_users
            (user_id, display_name, role, active, created_at_ms, updated_at_ms)
         VALUES (?1, ?2, ?3, 1, ?4, ?4)
         ON CONFLICT(user_id) DO UPDATE SET
            display_name = excluded.display_name,
            role = excluded.role,
            active = 1,
            updated_at_ms = excluded.updated_at_ms",
        params![user_id, display_name, role.as_str(), now_ms],
    )?;
    drop(conn);
    issue_business_os_capability_token(root, user_id, now_ms)
}

/// Issue a capability token for a trusted managed-control-plane session.
///
/// ctox.dev authenticates the tenant user on the managed subdomain, then calls
/// this path locally over the instance SSH control plane. This keeps Business OS
/// records on RxDB/WebRTC while allowing the browser command bus to carry a
/// native-signed role token instead of a spoofable actor claim.
pub fn issue_business_os_capability_token_for_managed_user(
    root: &Path,
    user_id: &str,
    display_name: &str,
    role: &str,
    now_ms: i64,
) -> anyhow::Result<(String, i64)> {
    issue_business_os_capability_token_for_managed_user_with_email(
        root,
        user_id,
        None,
        display_name,
        role,
        now_ms,
    )
}

pub fn issue_business_os_capability_token_for_managed_user_with_email(
    root: &Path,
    user_id: &str,
    email: Option<&str>,
    display_name: &str,
    role: &str,
    now_ms: i64,
) -> anyhow::Result<(String, i64)> {
    let user_id = user_id.trim();
    anyhow::ensure!(!user_id.is_empty(), "user id is required");
    let email = email
        .map(str::trim)
        .filter(|email| !email.is_empty())
        .map(str::to_ascii_lowercase);
    if let Some(email) = email.as_deref() {
        anyhow::ensure!(
            email.len() <= 320 && email.contains('@') && !email.chars().any(char::is_control),
            "email must be a bounded email address"
        );
    }
    let role = normalize_business_role(role);
    anyhow::ensure!(
        matches!(role.as_str(), "chef" | "admin" | "founder" | "user"),
        "role must be chef, admin, founder, or user"
    );
    let conn = open_store(root)?;
    seed_configured_business_users(&conn)?;
    let display_name = display_name.trim();
    let display_name = if display_name.is_empty() {
        user_id
    } else {
        display_name
    };
    conn.execute(
        "INSERT INTO business_users
            (user_id, display_name, role, active, created_at_ms, updated_at_ms)
         VALUES (?1, ?2, ?3, 1, ?4, ?4)
         ON CONFLICT(user_id) DO UPDATE SET
            display_name = excluded.display_name,
            role = excluded.role,
            active = 1,
            updated_at_ms = excluded.updated_at_ms",
        params![user_id, display_name, role.as_str(), now_ms],
    )?;
    drop(conn);
    issue_business_os_capability_token_until_with_identity(
        root,
        user_id,
        email.as_deref(),
        now_ms,
        now_ms + CAPABILITY_TOKEN_TTL_MS,
        None,
    )
}

