pub(super) fn rxdb_command_session(
    root: &Path,
    command: &BusinessCommand,
) -> anyhow::Result<BusinessOsSession> {
    rxdb_session_from_command(root, command, true)
}

pub(super) fn rxdb_authenticated_session(
    root: &Path,
    command: &BusinessCommand,
) -> anyhow::Result<BusinessOsSession> {
    rxdb_session_from_command(root, command, false)
}

pub(super) fn authenticated_rxdb_command_actor(
    root: &Path,
    document: &Value,
) -> anyhow::Result<BusinessOsSessionUser> {
    let command = BusinessCommand {
        origin: CommandOrigin::ReplicatedPeer,
        id: document
            .get("id")
            .and_then(Value::as_str)
            .map(str::to_string),
        module: document
            .get("module")
            .and_then(Value::as_str)
            .unwrap_or("browser")
            .to_string(),
        command_type: document
            .get("command_type")
            .or_else(|| document.get("type"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        record_id: document
            .get("record_id")
            .and_then(Value::as_str)
            .map(str::to_string),
        payload: document.get("payload").cloned().unwrap_or(Value::Null),
        client_context: document
            .get("client_context")
            .cloned()
            .unwrap_or(Value::Null),
    };
    rxdb_authenticated_session(root, &command)?
        .user
        .context("authenticated browser command actor is required")
}

pub(super) fn authorize_rxdb_browser_command(
    root: &Path,
    document: &Value,
) -> anyhow::Result<BusinessOsSessionUser> {
    let actor = authenticated_rxdb_command_actor(root, document)?;
    let command = BusinessCommand {
        origin: CommandOrigin::ReplicatedPeer,
        id: document
            .get("id")
            .and_then(Value::as_str)
            .map(str::to_string),
        module: "browser".to_string(),
        command_type: document
            .get("command_type")
            .or_else(|| document.get("type"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        record_id: document
            .get("record_id")
            .and_then(Value::as_str)
            .map(str::to_string),
        payload: document.get("payload").cloned().unwrap_or(Value::Null),
        client_context: document
            .get("client_context")
            .cloned()
            .unwrap_or(Value::Null),
    };
    let session = rxdb_authenticated_session(root, &command)?;
    let decision =
        module_policy_decision(root, &session, BusinessOsPermission::DataWrite, "browser")?;
    anyhow::ensure!(decision.allowed, "browser command permission denied");
    Ok(actor)
}

// SECURITY (per-command authorization trust boundary):
// The actor in `client_context` is asserted by the command author. For commands
// replicated over the WebRTC/RxDB data plane (`CommandOrigin::ReplicatedPeer`)
// that author is an untrusted browser peer admitted to the room only by the
// shared signaling secret, so its identity and role MUST come from a verified,
// native-signed capability token — never from the claimed actor. Without a valid
// token a replicated command resolves to an unprivileged, non-attributable
// principal (or is rejected outright when the operator requires tokens), so a
// spoofed chef/admin id cannot escalate. In-process commands (`TrustedLocal`:
// operator CLI, server-side handlers that already authenticated a session,
// internal projections) may trust their claimed actor. See `capability.rs`.
pub(super) fn rxdb_verified_identity_email(
    root: &Path,
    command: &BusinessCommand,
    expected_user_id: &str,
) -> Option<String> {
    let client_ctx = if let Value::String(ref value) = command.client_context {
        serde_json::from_str(value).unwrap_or_else(|_| command.client_context.clone())
    } else {
        command.client_context.clone()
    };
    let token = client_ctx
        .get("capability_token")
        .and_then(Value::as_str)
        .filter(|token| !token.is_empty())?;
    let claims = if matches!(&command.origin, CommandOrigin::ReplicatedPeer) {
        verified_webrtc_capability_claims(root, token)
    } else {
        verified_capability_claims(root, token)
    }?;
    if claims.user_id != expected_user_id {
        return None;
    }
    claims.email
}

fn rxdb_session_from_command(
    root: &Path,
    command: &BusinessCommand,
    require_manage_all: bool,
) -> anyhow::Result<BusinessOsSession> {
    let client_ctx = if let Value::String(ref s) = command.client_context {
        serde_json::from_str(s).unwrap_or_else(|_| command.client_context.clone())
    } else {
        command.client_context.clone()
    };
    let actor = client_ctx.get("actor").or_else(|| client_ctx.get("user"));
    let id = actor
        .and_then(|value| value.get("id"))
        .or_else(|| client_ctx.get("user_id"))
        .and_then(Value::as_str)
        .unwrap_or("rxdb-command")
        .to_string();
    let display_name = actor
        .and_then(|value| value.get("display_name"))
        .or_else(|| actor.and_then(|value| value.get("name")))
        .or_else(|| client_ctx.get("display_name"))
        .and_then(Value::as_str)
        .unwrap_or(id.as_str())
        .to_string();

    // Capability token (native-authoritative): when the command carries a valid
    // native-signed `capability_token`, the id + role come from the SIGNED token
    // for ANY origin, never from the claimed actor.
    let verified = client_ctx
        .get("capability_token")
        .and_then(Value::as_str)
        .filter(|token| !token.is_empty())
        .and_then(|token| {
            if matches!(&command.origin, CommandOrigin::ReplicatedPeer) {
                verified_webrtc_capability_claims(root, token)
            } else {
                verified_capability_claims(root, token)
            }
        });

    let (id, role, display_name) = if let Some(claims) = verified {
        (claims.user_id, claims.role, display_name)
    } else {
        match command.origin {
            // Operator / in-process caller: the claimed actor is trusted.
            CommandOrigin::TrustedLocal => {
                let trusted_user = trusted_rxdb_command_user(root, &id, &display_name)?;
                (id, trusted_user.role, trusted_user.display_name)
            }
            // Untrusted browser peer with no currently valid token: fail closed.
            // Offline behavior is explicit and deterministic; the browser keeps
            // the command pending instead of mutating under a synthetic actor.
            CommandOrigin::ReplicatedPeer => {
                anyhow::bail!("a valid capability token is required for Business OS commands")
            }
        }
    };
    let is_admin = role_can_manage(&role);
    let session = BusinessOsSession {
        ok: true,
        authenticated: true,
        auth_required: false,
        user: Some(BusinessOsSessionUser {
            id,
            display_name,
            role,
            is_admin,
        }),
        login_url: None,
        reason: None,
    };
    if require_manage_all {
        anyhow::ensure!(
            session_can_manage_all(&session),
            "chef or admin role required"
        );
    }
    Ok(session)
}

fn trusted_rxdb_command_user(
    root: &Path,
    actor_id: &str,
    actor_display_name: &str,
) -> anyhow::Result<BusinessOsUser> {
    let actor_id = actor_id.trim();
    let conn = open_store(root)?;
    seed_configured_business_users(&conn)?;
    if let Some(user) = active_business_user(&conn, actor_id)? {
        return Ok(user);
    }

    let user_count: i64 =
        conn.query_row("SELECT COUNT(*) FROM business_users", [], |row| row.get(0))?;
    if user_count == 0 && env::var("CTOX_BUSINESS_OS_REQUIRE_LOGIN").as_deref() != Ok("1") {
        let local = session(None, None);
        if let Some(user) = local.user {
            return Ok(BusinessOsUser {
                id: if actor_id.is_empty() {
                    user.id
                } else {
                    actor_id.to_owned()
                },
                display_name: if actor_display_name.trim().is_empty() {
                    user.display_name
                } else {
                    actor_display_name.to_owned()
                },
                role: normalize_business_role(&user.role),
                active: true,
                profile: empty_business_user_profile(),
                created_at_ms: 0,
                updated_at_ms: 0,
            });
        }
    }

    Ok(BusinessOsUser {
        id: if actor_id.is_empty() {
            "rxdb-command".to_owned()
        } else {
            actor_id.to_owned()
        },
        display_name: if actor_display_name.trim().is_empty() {
            actor_id.to_owned()
        } else {
            actor_display_name.to_owned()
        },
        role: "user".to_owned(),
        active: true,
        profile: empty_business_user_profile(),
        created_at_ms: 0,
        updated_at_ms: 0,
    })
}

fn active_business_user(
    conn: &Connection,
    actor_id: &str,
) -> anyhow::Result<Option<BusinessOsUser>> {
    let actor_id = actor_id.trim();
    if actor_id.is_empty() {
        return Ok(None);
    }
    Ok(conn
        .query_row(
            "SELECT user_id, display_name, role, active, profile_json, created_at_ms, updated_at_ms
         FROM business_users
         WHERE user_id = ?1 AND active = 1",
            params![actor_id],
            |row| {
                let profile_json: String = row.get(4)?;
                Ok(BusinessOsUser {
                    id: row.get(0)?,
                    display_name: row.get(1)?,
                    role: normalize_business_role(&row.get::<_, String>(2)?),
                    active: row.get::<_, i64>(3)? != 0,
                    profile: parse_business_user_profile_json(&profile_json),
                    created_at_ms: row.get(5)?,
                    updated_at_ms: row.get(6)?,
                })
            },
        )
        .optional()?)
}

pub(crate) fn finalize_runtime_app_action(
    root: &Path,
    document: &Value,
    status: &str,
    result: Value,
) -> anyhow::Result<Value> {
    let command = BusinessCommand {
        origin: CommandOrigin::ReplicatedPeer,
        id: document
            .get("command_id")
            .or_else(|| document.get("id"))
            .and_then(Value::as_str)
            .map(str::to_owned),
        module: document
            .get("module")
            .and_then(Value::as_str)
            .unwrap_or("ctox")
            .to_owned(),
        command_type: app_runtime::APP_ACTION_COMMAND_TYPE.to_owned(),
        record_id: document
            .get("record_id")
            .and_then(Value::as_str)
            .map(str::to_owned),
        payload: document.get("payload").cloned().unwrap_or(Value::Null),
        client_context: document
            .get("client_context")
            .cloned()
            .unwrap_or(Value::Null),
    };
    write_rxdb_control_command_outcome(root, &command, status, None, Some(status), result)
}

pub(super) struct RecoverablePersonResearchCommand {
    pub(super) command: BusinessCommand,
    pub(super) status: String,
}

pub(super) struct TerminalPersonResearchProjectionCandidate {
    pub(super) command: BusinessCommand,
    pub(super) terminal_status: String,
    pub(super) result: Value,
    pub(super) error_message: Option<String>,
}

pub(super) fn authorize_recoverable_person_research_command(
    root: &Path,
    command: &BusinessCommand,
) -> anyhow::Result<BusinessCommand> {
    anyhow::ensure!(
        command.command_type == "web_stack.person_research",
        "person-research recovery requires web_stack.person_research"
    );
    authorize_recoverable_background_control_command(root, command)
}

pub(super) fn authorize_recoverable_background_control_command(
    root: &Path,
    command: &BusinessCommand,
) -> anyhow::Result<BusinessCommand> {
    let permission = recoverable_background_control_permission(&command.command_type)
        .context("command type is not recoverable")?;
    if let Ok(session) = rxdb_authenticated_session(root, command) {
        let decision = module_policy_decision(root, &session, permission, &command.module)?;
        anyhow::ensure!(
            decision.allowed,
            "accepted recoverable command authorization is no longer valid: {}",
            decision.display_reason
        );
        return Ok(command.clone());
    }

    let command_id = command
        .id
        .as_deref()
        .context("recoverable command id is required")?;
    let projection = channels::business_command_projection(root, command_id)?;
    let authorization = projection
        .get("native_authorization")
        .context("accepted recoverable command has no native authorization receipt")?;
    anyhow::ensure!(
        authorization.get("contract").and_then(Value::as_str)
            == Some("ctox-business-command-authorization-v1"),
        "accepted recoverable command has an invalid native authorization receipt"
    );
    anyhow::ensure!(
        authorization.get("allowed").and_then(Value::as_bool) == Some(true),
        "accepted recoverable command was not authorized"
    );
    anyhow::ensure!(
        authorization.get("permission").and_then(Value::as_str) == Some(permission.as_str()),
        "accepted recoverable command authorization permission changed"
    );
    anyhow::ensure!(
        authorization.get("scope_type").and_then(Value::as_str) == Some("module")
            && authorization.get("scope_id").and_then(Value::as_str)
                == Some(command.module.as_str()),
        "accepted recoverable command authorization scope changed"
    );
    let actor = authorization
        .get("actor")
        .filter(|actor| actor.get("trusted").and_then(Value::as_bool) == Some(true))
        .context("accepted recoverable command has no trusted authorized actor")?;
    let actor_id = actor
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .context("accepted recoverable command authorized actor is missing")?;

    let mut recovered = command.clone();
    recovered.origin = CommandOrigin::TrustedLocal;
    let mut recovered_context = recovered
        .client_context
        .as_object()
        .cloned()
        .unwrap_or_default();
    recovered_context.insert(
        "owner_user_id".to_string(),
        Value::String(actor_id.to_string()),
    );
    recovered_context.insert("actor".to_string(), actor.clone());
    recovered_context.insert(
        "recovered_from".to_string(),
        Value::String("ctox-business-command-authorization-v1".to_string()),
    );
    recovered.client_context = Value::Object(recovered_context);
    let conn = open_store(root)?;
    conn.execute(
        "UPDATE business_commands
         SET client_context_json = ?1, observed_at_ms = ?2
         WHERE command_id = ?3",
        params![
            serde_json::to_string(&recovered.client_context)?,
            now_ms() as i64,
            command_id,
        ],
    )?;
    drop(conn);
    let session = rxdb_authenticated_session(root, &recovered)?;
    let decision = module_policy_decision(root, &session, permission, &recovered.module)?;
    anyhow::ensure!(
        decision.allowed,
        "accepted recoverable command authorization is no longer valid: {}",
        decision.display_reason
    );
    Ok(recovered)
}

pub(super) fn recoverable_person_research_commands(
    root: &Path,
) -> anyhow::Result<Vec<RecoverablePersonResearchCommand>> {
    let conn = open_store(root)?;
    let mut statement = conn.prepare(
        "SELECT command_id, module, record_id, payload_json, client_context_json, status
         FROM business_commands
         WHERE command_type = 'web_stack.person_research'
           AND status IN ('accepted', 'running')
         ORDER BY observed_at_ms ASC",
    )?;
    let rows = statement.query_map([], |row| {
        let command_id: String = row.get(0)?;
        let module: String = row.get(1)?;
        let record_id: String = row.get(2)?;
        let payload_json: String = row.get(3)?;
        let client_context_json: String = row.get(4)?;
        let status: String = row.get(5)?;
        Ok(RecoverablePersonResearchCommand {
            command: BusinessCommand {
                id: Some(command_id),
                module,
                command_type: "web_stack.person_research".to_string(),
                record_id: (!record_id.trim().is_empty()).then_some(record_id),
                payload: serde_json::from_str(&payload_json).unwrap_or(Value::Null),
                client_context: serde_json::from_str(&client_context_json).unwrap_or(Value::Null),
                origin: CommandOrigin::ReplicatedPeer,
            },
            status,
        })
    })?;
    rows.collect::<Result<Vec<_>, _>>().map_err(Into::into)
}

pub(super) fn terminal_person_research_projection_candidates(
    root: &Path,
) -> anyhow::Result<Vec<TerminalPersonResearchProjectionCandidate>> {
    let store_path = business_os_store_path(root);
    if !store_path.exists() {
        return Ok(Vec::new());
    }
    let conn = Connection::open_with_flags(
        &store_path,
        OpenFlags::SQLITE_OPEN_READ_ONLY
            | OpenFlags::SQLITE_OPEN_NO_MUTEX
            | OpenFlags::SQLITE_OPEN_URI,
    )
    .with_context(|| {
        format!(
            "open Business OS store for person-research recovery {}",
            store_path.display()
        )
    })?;
    conn.busy_timeout(crate::persistence::sqlite_busy_timeout_duration())
        .context("configure person-research recovery busy_timeout")?;
    let canonical_path = crate::paths::core_db(root);
    let mut canonical_uri = Url::from_file_path(&canonical_path).map_err(|_| {
        anyhow::anyhow!(
            "build read-only canonical command database URI for {}",
            canonical_path.display()
        )
    })?;
    canonical_uri.query_pairs_mut().append_pair("mode", "ro");
    conn.execute(
        "ATTACH DATABASE ?1 AS canonical_person_research",
        [canonical_uri.as_str()],
    )
    .with_context(|| {
        format!(
            "attach canonical command database for person-research recovery {}",
            canonical_path.display()
        )
    })?;
    let mut statement = conn.prepare(
        "SELECT command.command_id, command.module, command.record_id,
                command.payload_json, command.client_context_json, command.status,
                CASE WHEN command.module = 'outbound-lead-generation'
                       AND command.record_id <> ''
                       AND json_extract(command.client_context_json, '$.surface') = 'business_os_command_session'
                       AND json_type(command.payload_json, '$.writeback_contract') IS NULL
                       AND COALESCE(json_extract(lead.payload_json, '$.payload.last_research_command_id'), '') <> command.command_id
                       AND NOT EXISTS (
                         SELECT 1 FROM business_commands AS later
                          WHERE later.command_type = 'web_stack.person_research'
                            AND later.module = command.module
                            AND later.record_id = command.record_id
                            AND later.status IN ('completed', 'failed', 'cancelled')
                            AND later.observed_at_ms > command.observed_at_ms
                       )
                     THEN 1 ELSE 0 END AS needs_legacy_lead_writeback
         FROM business_commands AS command
         LEFT JOIN business_records AS stored
           ON stored.collection = 'business_commands'
          AND stored.record_id = command.command_id
          AND stored.deleted = 0
         LEFT JOIN canonical_person_research.business_command_aggregates AS canonical
           ON canonical.command_id = command.command_id
         LEFT JOIN business_records AS lead
           ON lead.collection = 'outbound_lead_generation_leads'
          AND lead.record_id = command.record_id
          AND lead.deleted = 0
         WHERE command.command_type = 'web_stack.person_research'
           AND command.status IN ('completed', 'failed', 'cancelled')
           AND (
             COALESCE(json_extract(stored.payload_json, '$.terminal_status'), 'none')
               NOT IN ('completed', 'failed', 'cancelled')
             OR COALESCE(canonical.terminal_status, 'none')
               NOT IN ('completed', 'failed', 'cancelled')
             OR (
               command.module = 'outbound-lead-generation'
               AND command.record_id <> ''
               AND json_extract(command.client_context_json, '$.surface') = 'business_os_command_session'
               AND json_type(command.payload_json, '$.writeback_contract') IS NULL
               AND COALESCE(json_extract(lead.payload_json, '$.payload.last_research_command_id'), '') <> command.command_id
               AND NOT EXISTS (
                 SELECT 1 FROM business_commands AS later
                  WHERE later.command_type = 'web_stack.person_research'
                    AND later.module = command.module
                    AND later.record_id = command.record_id
                    AND later.status IN ('completed', 'failed', 'cancelled')
                    AND later.observed_at_ms > command.observed_at_ms
               )
             )
           )
         ORDER BY command.observed_at_ms ASC",
    )?;
    let rows = statement.query_map([], |row| {
        Ok((
            row.get::<_, String>(0)?,
            row.get::<_, String>(1)?,
            row.get::<_, String>(2)?,
            row.get::<_, String>(3)?,
            row.get::<_, String>(4)?,
            row.get::<_, String>(5)?,
            row.get::<_, bool>(6)?,
        ))
    })?;
    let mut candidates = Vec::new();
    for row in rows {
        let (
            command_id,
            module,
            record_id,
            payload_json,
            client_context_json,
            terminal_status,
            needs_legacy_lead_writeback,
        ) = row?;
        let stored =
            stored_rxdb_business_command_outcome(&conn, &command_id)?.with_context(|| {
                format!("terminal person-research projection missing for {command_id}")
            })?;
        let canonical = channels::business_command_projection(root, &command_id)?;
        let canonical_terminal = canonical
            .get("terminal_status")
            .and_then(Value::as_str)
            .unwrap_or("none");
        let stored_terminal = stored
            .get("terminal_status")
            .and_then(Value::as_str)
            .unwrap_or("none");
        if canonical_terminal == terminal_status
            && stored_terminal == terminal_status
            && !needs_legacy_lead_writeback
        {
            continue;
        }
        let recovery_terminal_status =
            matches!(canonical_terminal, "completed" | "failed" | "cancelled")
                .then_some(canonical_terminal)
                .unwrap_or(terminal_status.as_str())
                .to_string();
        let recovery_source = if canonical_terminal == recovery_terminal_status {
            &canonical
        } else {
            &stored
        };
        let result = recovery_source
            .get("result")
            .cloned()
            .unwrap_or(Value::Null);
        let error_message = recovery_source
            .get("error_message")
            .or_else(|| result.get("error"))
            .and_then(Value::as_str)
            .map(str::to_string);
        let mut payload = serde_json::from_str(&payload_json).unwrap_or(Value::Null);
        if needs_legacy_lead_writeback {
            payload["writeback_contract"] = serde_json::json!({
                "collection": "outbound_lead_generation_leads",
                "allowed_collections": ["outbound_lead_generation_leads"],
                "record_ids": [record_id],
                "command_type": "web_stack.person_research",
                "min_independent_sources": 2,
                "recovered_from": "missing_execute_action_writeback_contract"
            });
        }
        candidates.push(TerminalPersonResearchProjectionCandidate {
            command: BusinessCommand {
                id: Some(command_id),
                module,
                command_type: "web_stack.person_research".to_string(),
                record_id: (!record_id.trim().is_empty()).then_some(record_id),
                payload,
                client_context: serde_json::from_str(&client_context_json).unwrap_or(Value::Null),
                origin: CommandOrigin::TrustedLocal,
            },
            terminal_status: recovery_terminal_status,
            result,
            error_message,
        });
    }
    Ok(candidates)
}

/// Persist the native-enriched v2 command document as the canonical Business OS
/// projection. The caller has already completed the canonical intake/side
/// effect and will mirror the same document into RxDB afterwards.
pub(crate) fn persist_business_command_lifecycle_projection(
    root: &Path,
    document: &Value,
) -> anyhow::Result<()> {
    let command_id = document
        .get("command_id")
        .or_else(|| document.get("id"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .context("business command lifecycle projection is missing command_id")?;
    let conn = open_store(root)?;
    let exists = conn
        .query_row(
            "SELECT 1 FROM business_commands WHERE command_id = ?1",
            params![command_id],
            |_| Ok(()),
        )
        .optional()?
        .is_some();
    anyhow::ensure!(
        exists,
        "cannot persist lifecycle projection before canonical intake"
    );
    let updated_at_ms = document
        .get("updated_at_ms")
        .and_then(Value::as_i64)
        .unwrap_or_else(|| now_ms() as i64);
    upsert_business_record(
        &conn,
        "business_commands",
        command_id,
        updated_at_ms,
        document.clone(),
    )
}

/// Deliver canonical command lifecycle changes from the core SQLite outbox.
/// Canonical queue/control progress never depends on either compatibility
/// store being available; failed deliveries remain retryable (and eventually
/// visible as dead letters) in `ctox.sqlite3`.
pub(crate) fn deliver_business_command_outbox(root: &Path, limit: usize) -> anyhow::Result<Value> {
    const MAX_ATTEMPTS: u32 = 8;
    let events = channels::pending_business_command_outbox(root, limit)?;
    let mut delivered = 0_u64;
    let mut failed = 0_u64;
    for event in events {
        let projection = channels::business_command_projection(root, &event.command_id);
        let delivery = projection.and_then(|projection| match event.destination.as_str() {
            "business-os" => {
                let command_id = event.command_id.as_str();
                let module = projection
                    .get("module")
                    .and_then(Value::as_str)
                    .unwrap_or("ctox");
                let command_type = projection
                    .get("command_type")
                    .and_then(Value::as_str)
                    .unwrap_or("business_os.command");
                let record_id = projection
                    .get("record_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                let status = projection
                    .get("status")
                    .and_then(Value::as_str)
                    .unwrap_or("accepted");
                let observed_at_ms = projection
                    .get("updated_at_ms")
                    .and_then(Value::as_i64)
                    .unwrap_or_else(|| now_ms() as i64);
                let mut conn = open_store(root)?;
                let tx = conn.transaction()?;
                tx.execute(
                    "INSERT INTO business_commands
                        (command_id, module, command_type, record_id, status, payload_json,
                         client_context_json, observed_at_ms)
                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)
                     ON CONFLICT(command_id) DO UPDATE SET
                        module = excluded.module,
                        command_type = excluded.command_type,
                        record_id = excluded.record_id,
                        status = excluded.status,
                        payload_json = excluded.payload_json,
                        client_context_json = excluded.client_context_json,
                        observed_at_ms = excluded.observed_at_ms",
                    params![
                        command_id,
                        module,
                        command_type,
                        record_id,
                        status,
                        serde_json::to_string(projection.get("payload").unwrap_or(&Value::Null))?,
                        serde_json::to_string(
                            projection.get("client_context").unwrap_or(&Value::Null)
                        )?,
                        observed_at_ms,
                    ],
                )?;
                upsert_business_record(
                    &tx,
                    "business_commands",
                    command_id,
                    observed_at_ms,
                    projection,
                )?;
                tx.commit()?;
                Ok(())
            }
            "rxdb" => {
                let updated_at_ms = projection
                    .get("updated_at_ms")
                    .and_then(Value::as_i64)
                    .unwrap_or_else(|| now_ms() as i64);
                upsert_rxdb_collection_record(
                    root,
                    "business_commands",
                    &event.command_id,
                    updated_at_ms,
                    projection,
                )
            }
            destination => anyhow::bail!("unsupported command outbox destination `{destination}`"),
        });
        match delivery {
            Ok(()) => {
                channels::mark_business_command_outbox_delivered(root, &event.event_id)?;
                delivered = delivered.saturating_add(1);
            }
            Err(error) => {
                channels::mark_business_command_outbox_failed(
                    root,
                    &event.event_id,
                    &format!(
                        "{} delivery of {} v{} ({}) failed: {error:#}",
                        event.destination,
                        event.command_id,
                        event.projection_version,
                        event.event_type
                    ),
                    MAX_ATTEMPTS,
                )?;
                failed = failed.saturating_add(1);
            }
        }
    }
    Ok(serde_json::json!({
        "processed": delivered.saturating_add(failed),
        "delivered": delivered,
        "failed": failed,
    }))
}

pub(crate) fn record_business_command_intake_failure(
    root: &Path,
    document: &Value,
    error_message: &str,
    retry_budget: u32,
) -> anyhow::Result<Value> {
    let command_id = document
        .get("command_id")
        .or_else(|| document.get("id"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .context("business command intake failure is missing command_id")?;
    let command = BusinessCommand {
        origin: CommandOrigin::TrustedLocal,
        id: Some(command_id.to_string()),
        module: document
            .get("module")
            .and_then(Value::as_str)
            .unwrap_or("ctox")
            .to_string(),
        command_type: document
            .get("command_type")
            .or_else(|| document.get("type"))
            .and_then(Value::as_str)
            .unwrap_or("business_os.command")
            .to_string(),
        record_id: document
            .get("record_id")
            .and_then(Value::as_str)
            .map(str::to_string),
        payload: document.get("payload").cloned().unwrap_or(Value::Null),
        client_context: document
            .get("client_context")
            .cloned()
            .unwrap_or(Value::Null),
    };
    let core_outcome = channels::record_business_command_intake_failure(
        root,
        business_command_core_claim(command_id, &command)?,
        error_message,
        retry_budget,
    )?;
    if core_outcome
        .get("canonical_failure_created")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        let _ = deliver_business_command_outbox(root, 10);
    }
    return Ok(core_outcome);
}

pub(crate) fn resolve_business_command_intake_failures(
    root: &Path,
    command_id: &str,
) -> anyhow::Result<usize> {
    let core_resolved = channels::resolve_business_command_intake_failures(root, command_id)?;
    let conn = open_store(root)?;
    let compatibility_resolved = conn.execute(
        "UPDATE business_command_intake_failures
         SET resolved_at_ms = ?2
         WHERE command_id = ?1 AND resolved_at_ms IS NULL",
        params![command_id, now_ms() as i64],
    )?;
    Ok(core_resolved.saturating_add(compatibility_resolved))
}

pub fn business_command_diagnostics(root: &Path) -> anyhow::Result<Value> {
    let conn = open_store(root)?;
    let mut status_counts = serde_json::Map::new();
    let mut stmt = conn.prepare(
        "SELECT status, COUNT(*) FROM business_commands GROUP BY status ORDER BY status",
    )?;
    for row in stmt.query_map([], |row| {
        Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?))
    })? {
        let (status, count) = row?;
        status_counts.insert(status, Value::from(count));
    }
    drop(stmt);
    let canonical_count = conn.query_row("SELECT COUNT(*) FROM business_commands", [], |row| {
        row.get::<_, u64>(0)
    })?;
    let canonical_without_projection = conn.query_row(
        "SELECT COUNT(*)
         FROM business_commands command
         LEFT JOIN business_records projection
           ON projection.collection = 'business_commands'
          AND projection.record_id = command.command_id
          AND projection.deleted = 0
         WHERE projection.record_id IS NULL",
        [],
        |row| row.get::<_, u64>(0),
    )?;
    let projection_without_canonical = conn.query_row(
        "SELECT COUNT(*)
         FROM business_records projection
         LEFT JOIN business_commands command
           ON command.command_id = projection.record_id
         WHERE projection.collection = 'business_commands'
           AND projection.deleted = 0
           AND command.command_id IS NULL",
        [],
        |row| row.get::<_, u64>(0),
    )?;
    let oldest_nonterminal_query = format!(
        "SELECT MIN(observed_at_ms)
         FROM business_commands
         WHERE status NOT IN ({})",
        crate::command_lifecycle::CTOX_COMMAND_TERMINAL_OUTCOME_SQL_LIST,
    );
    let oldest_nonterminal_at_ms = conn.query_row(&oldest_nonterminal_query, [], |row| {
        row.get::<_, Option<u64>>(0)
    })?;
    let (open_intake_failures, exhausted_intake_failures, oldest_failure_at_ms) = conn.query_row(
        "SELECT COUNT(*),
                COALESCE(SUM(CASE WHEN exhausted = 1 THEN 1 ELSE 0 END), 0),
                MIN(observed_at_ms)
         FROM business_command_intake_failures
         WHERE resolved_at_ms IS NULL",
        [],
        |row| {
            Ok((
                row.get::<_, u64>(0)?,
                row.get::<_, u64>(1)?,
                row.get::<_, Option<u64>>(2)?,
            ))
        },
    )?;
    let mut linked_tasks = Vec::new();
    {
        let mut stmt = conn.prepare(
            "SELECT record_id, payload_json
             FROM business_records
             WHERE collection = 'business_commands' AND deleted = 0",
        )?;
        let rows = stmt.query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
        })?;
        for row in rows {
            let (command_id, payload_json) = row?;
            let payload: Value = serde_json::from_str(&payload_json).unwrap_or(Value::Null);
            if payload.get("execution_mode").and_then(Value::as_str) == Some("control") {
                continue;
            }
            let task_id = payload
                .get("execution_task_id")
                .or_else(|| payload.get("task_id"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty());
            if let Some(task_id) = task_id {
                linked_tasks.push((command_id, task_id.to_string()));
            }
        }
    }
    drop(conn);
    let mut orphan_links = Vec::new();
    for (command_id, task_id) in &linked_tasks {
        if channels::load_queue_task(root, task_id)?.is_none() {
            orphan_links.push(serde_json::json!({
                "command_id": command_id,
                "execution_task_id": task_id,
            }));
        }
    }
    let now = now_ms() as u64;
    let core = channels::business_command_core_diagnostics(root)?;
    Ok(serde_json::json!({
        "schema": "ctox.business_os.command_diagnostics.v1",
        "captured_at_ms": now,
        "canonical": {
            "count": canonical_count,
            "by_status": status_counts,
            "oldest_nonterminal_age_ms": oldest_nonterminal_at_ms
                .map(|value| now.saturating_sub(value))
                .unwrap_or_default(),
        },
        "intake_failures": {
            "open_count": open_intake_failures,
            "exhausted_count": exhausted_intake_failures,
            "oldest_open_age_ms": oldest_failure_at_ms
                .map(|value| now.saturating_sub(value))
                .unwrap_or_default(),
        },
        "projections": {
            "canonical_without_projection": canonical_without_projection,
            "projection_without_canonical": projection_without_canonical,
        },
        "task_links": {
            "count": linked_tasks.len(),
            "orphan_count": orphan_links.len(),
            "orphans": orphan_links,
        },
        "core": core,
        "duplicate_effect_count": core
            .get("duplicate_effect_count")
            .cloned()
            .unwrap_or(Value::Null),
        "duplicate_effect_evidence": "canonical core effect ledger",
    }))
}

pub(super) fn is_customers_active_command(command_type: &str) -> bool {
    matches!(
        command_type,
        "customers.account.create"
            | "customers.account.update"
            | "customers.account.archive"
            | "customers.contact.create"
            | "customers.contact.update"
            | "customers.contact.archive"
            | "customers.opportunity.create"
            | "customers.opportunity.update"
            | "customers.opportunity.move_stage"
            | "customers.opportunity.close_won"
            | "customers.opportunity.close_lost"
            | "customers.task.create"
            | "customers.task.update"
            | "customers.task.complete"
            | "customers.note.create"
            | "customers.note.update"
            | "customers.activity.record"
            | "customers.view.save"
            | "customers.import.from_outbound"
            | "customers.dedupe.resolve"
    )
}

fn process_documents_report_command(
    root: &Path,
    conn: &Connection,
    command_id: &str,
    command: &BusinessCommand,
    queue_task: Option<&channels::QueueTaskView>,
    reply_text: Option<&str>,
) -> anyhow::Result<CommandAccepted> {
    let writeback = (|| {
        let lineage = document_report_lineage(root, command)?;
        writeback_generated_docx(root, conn, command_id, command, reply_text, &lineage)
    })();
    match writeback {
        Ok(result) => {
            let completed_at_ms = now_ms() as i64;
            conn.execute(
                "UPDATE business_commands SET status = 'accepted', observed_at_ms = ?2 WHERE command_id = ?1",
                params![command_id, completed_at_ms],
            )?;
            upsert_business_record(
                conn,
                "business_commands",
                command_id,
                completed_at_ms,
                serde_json::json!({
                    "id": command_id,
                    "command_id": command_id,
                    "module": command.module.clone(),
                    "command_type": command.command_type.clone(),
                    "record_id": command.record_id.clone().unwrap_or_default(),
                    "status": "accepted",
                    "inbound_channel": command_inbound_channel(command),
                    "task_id": queue_task.map(|task| task.message_key.clone()),
                    "task_status": queue_task.map(|task| normalize_queue_status(&task.route_status)),
                    "payload": command.payload.clone(),
                    "client_context": command.client_context.clone(),
                    "result": result,
                    "updated_at_ms": completed_at_ms
                }),
            )?;
            refresh_queue_task_projection(
                root,
                conn,
                None,
                command_id,
                command,
                queue_task,
                completed_at_ms,
            )?;
            Ok(CommandAccepted {
                ok: true,
                command_id: command_id.to_string(),
                status: "completed",
                task_id: queue_task.map(|task| task.message_key.clone()),
                task_status: Some("completed".to_string()),
                ..CommandAccepted::default()
            })
        }
        Err(err) => {
            let failed_at_ms = now_ms() as i64;
            conn.execute(
                "UPDATE business_commands SET status = 'failed', observed_at_ms = ?2 WHERE command_id = ?1",
                params![command_id, failed_at_ms],
            )?;
            upsert_business_record(
                conn,
                "business_commands",
                command_id,
                failed_at_ms,
                serde_json::json!({
                    "id": command_id,
                    "command_id": command_id,
                    "module": command.module.clone(),
                    "command_type": command.command_type.clone(),
                    "record_id": command.record_id.clone().unwrap_or_default(),
                    "status": "failed",
                    "inbound_channel": command_inbound_channel(command),
                    "task_id": queue_task.map(|task| task.message_key.clone()),
                    "task_status": "failed",
                    "error": err.to_string(),
                    "payload": command.payload.clone(),
                    "client_context": command.client_context.clone(),
                    "updated_at_ms": failed_at_ms
                }),
            )?;
            refresh_queue_task_projection(
                root,
                conn,
                None,
                command_id,
                command,
                queue_task,
                failed_at_ms,
            )?;
            Err(err)
        }
    }
}

fn process_systematic_research_command(
    root: &Path,
    conn: &Connection,
    command_id: &str,
    command: &BusinessCommand,
    queue_task: Option<&channels::QueueTaskView>,
    reply_text: &str,
) -> anyhow::Result<CommandAccepted> {
    let completed_at_ms = now_ms() as i64;
    let evidence = match systematic_research_evidence_snapshot(root, command_id, command) {
        Ok(evidence) => evidence,
        Err(error) => {
            persist_systematic_research_failure(
                root,
                conn,
                command_id,
                command,
                queue_task,
                &error,
                completed_at_ms,
            )?;
            return Err(error);
        }
    };
    conn.execute(
        "UPDATE business_commands SET status = 'accepted', observed_at_ms = ?2 WHERE command_id = ?1",
        params![command_id, completed_at_ms],
    )?;

    let mut terminal_queue_task = queue_task.cloned();
    if let Some(task) = queue_task {
        terminal_queue_task = channels::load_queue_task(root, &task.message_key)
            .ok()
            .flatten()
            .or_else(|| Some(task.clone()));
    }

    let task_id = command
        .record_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| first_string_field(&command.payload, &["task_id", "research_task_id"]))
        .unwrap_or_default();
    let task_queue_id = terminal_queue_task
        .as_ref()
        .map(|task| task.message_key.clone())
        .or_else(|| find_queue_task_for_command(root, command_id));
    let knowledge_domain = first_string_field(&command.payload, &["knowledge_domain", "domain"])
        .or_else(|| first_string_field(&command.client_context, &["knowledge_domain", "domain"]))
        .unwrap_or_default();
    let reply_summary = clip_text(reply_text, 1200);
    let result = serde_json::json!({
        "summary": reply_summary,
        "knowledge_domain": knowledge_domain.clone(),
        "task_id": task_id.clone(),
        "task_queue_id": task_queue_id.clone(),
        "identified_count": evidence.identified_count,
        "accepted_count": evidence.accepted_count,
        "used_count": evidence.used_count,
        "source_receipt_links": evidence.source_receipt_links,
        "source_receipt_snapshot_hashes": evidence.source_receipt_snapshot_hashes,
        "knowledge_version": evidence.knowledge_version,
        "completed_at_ms": completed_at_ms
    });
    let mut rxdb_writers = RxdbProjectionWriterCache::new(root);

    if !task_id.is_empty() {
        let mut task_payload = load_rxdb_collection_record(root, "research_tasks", &task_id)?
            .unwrap_or_else(|| {
                serde_json::json!({
                    "id": task_id,
                    "title": first_string_field(&command.payload, &["task_title", "title"]).unwrap_or_else(|| command_title(command)),
                    "status": "ready",
                    "knowledge_domain": knowledge_domain,
                    "payload": {},
                    "created_at_ms": completed_at_ms,
                    "updated_at_ms": completed_at_ms
                })
            });
        if let Some(object) = task_payload.as_object_mut() {
            object.insert("status".to_string(), Value::String("ready".to_string()));
            object.insert("updated_at_ms".to_string(), Value::from(completed_at_ms));
            object
                .entry("knowledge_domain".to_string())
                .or_insert_with(|| Value::String(knowledge_domain.clone()));
            let payload = object
                .entry("payload".to_string())
                .or_insert_with(|| serde_json::json!({}));
            if let Some(payload_object) = payload.as_object_mut() {
                payload_object.insert("last_run".to_string(), result.clone());
            }
        }
        upsert_business_record(
            conn,
            "research_tasks",
            &task_id,
            completed_at_ms,
            task_payload.clone(),
        )?;
        upsert_rxdb_collection_record_cached(
            root,
            Some(&mut rxdb_writers),
            "research_tasks",
            &task_id,
            completed_at_ms,
            task_payload,
        )?;
    }

    let (run_id, mut run_payload) = find_rxdb_collection_record_by_string_field(
        root,
        "research_runs",
        "command_id",
        command_id,
    )?
    .unwrap_or_else(|| {
        (
            format!("research_run_{completed_at_ms}"),
            serde_json::json!({
                "task_id": task_id.clone(),
                "status": "queued",
                "command_id": command_id,
                "task_queue_id": task_queue_id.clone(),
                "identified_count": 0,
                "accepted_count": 0,
                "used_count": 0,
                "payload": {},
                "created_at_ms": completed_at_ms,
                "updated_at_ms": completed_at_ms
            }),
        )
    });
    if let Some(object) = run_payload.as_object_mut() {
        object.insert("id".to_string(), Value::String(run_id.clone()));
        object.insert("task_id".to_string(), Value::String(task_id.clone()));
        object.insert("status".to_string(), Value::String("completed".to_string()));
        object.insert(
            "command_id".to_string(),
            Value::String(command_id.to_string()),
        );
        if let Some(task_queue_id) = task_queue_id.as_deref() {
            object.insert(
                "task_queue_id".to_string(),
                Value::String(task_queue_id.to_string()),
            );
        }
        object.insert("updated_at_ms".to_string(), Value::from(completed_at_ms));
        object.insert(
            "identified_count".to_string(),
            Value::from(evidence.identified_count),
        );
        object.insert(
            "accepted_count".to_string(),
            Value::from(evidence.accepted_count),
        );
        object.insert("used_count".to_string(), Value::from(evidence.used_count));
        let payload = object
            .entry("payload".to_string())
            .or_insert_with(|| serde_json::json!({}));
        if let Some(payload_object) = payload.as_object_mut() {
            payload_object.insert("result".to_string(), result.clone());
        }
    }
    upsert_business_record(
        conn,
        "research_runs",
        &run_id,
        completed_at_ms,
        run_payload.clone(),
    )?;
    upsert_rxdb_collection_record_cached(
        root,
        Some(&mut rxdb_writers),
        "research_runs",
        &run_id,
        completed_at_ms,
        run_payload,
    )?;

    let command_payload = serde_json::json!({
        "id": command_id,
        "command_id": command_id,
        "module": command.module.clone(),
        "command_type": command.command_type.clone(),
        "record_id": command.record_id.clone().unwrap_or_default(),
        "status": "accepted",
        "inbound_channel": command_inbound_channel(command),
        "task_id": task_queue_id,
        "task_status": terminal_queue_task.as_ref().map(|task| normalize_queue_status(&task.route_status)),
        "payload": command.payload.clone(),
        "client_context": command.client_context.clone(),
        "result": result,
        "updated_at_ms": completed_at_ms
    });
    upsert_business_record(
        conn,
        "business_commands",
        command_id,
        completed_at_ms,
        command_payload.clone(),
    )?;
    upsert_rxdb_collection_record_cached(
        root,
        Some(&mut rxdb_writers),
        "business_commands",
        command_id,
        completed_at_ms,
        command_payload,
    )?;
    refresh_queue_task_projection(
        root,
        conn,
        Some(&mut rxdb_writers),
        command_id,
        command,
        terminal_queue_task.as_ref().or(queue_task),
        completed_at_ms,
    )?;

    Ok(CommandAccepted {
        ok: true,
        command_id: command_id.to_string(),
        status: "completed",
        task_id: task_queue_id,
        task_status: Some("completed".to_string()),
        ..CommandAccepted::default()
    })
}

pub fn update_ctox_task(
    root: &Path,
    session: &BusinessOsSession,
    mutation: CtoxTaskUpdateMutation,
) -> anyhow::Result<Value> {
    let task_id = resolve_ctox_task_id(root, &mutation.task_id)?;
    anyhow::ensure!(!task_id.is_empty(), "task_id is required");
    anyhow::ensure!(
        session_can_manage_task(root, session, &task_id)?,
        "chef or admin role required"
    );
    let title = mutation.title.and_then(non_empty_trimmed);
    let prompt = mutation.prompt.and_then(non_empty_trimmed);
    let priority = mutation.priority.and_then(non_empty_trimmed);
    anyhow::ensure!(
        title.is_some() || prompt.is_some() || priority.is_some(),
        "nothing to update"
    );

    let conn = open_store(root)?;
    seed_session_user(&conn, session)?;
    let updated = channels::update_queue_task(
        root,
        channels::QueueTaskUpdateRequest {
            message_key: task_id.clone(),
            title,
            prompt,
            priority,
            status_note: Some(format!(
                "business-os: edited by {}",
                session_user_label(session)
            )),
            ..Default::default()
        },
    )?;
    let now = now_ms() as i64;
    let command_id = queue_projection_command_id(&conn, &task_id)?;
    let structured_status =
        queue_projection_structured_status(&conn, command_id.as_deref(), &task_id)?;
    write_queue_task_projection(&conn, command_id.as_deref(), &updated, now)?;
    Ok(serde_json::json!({
        "ok": true,
        "task": queue_task_payload(
            command_id.as_deref(),
            &updated,
            structured_status.as_deref(),
            now,
        )
    }))
}

pub fn delete_ctox_task(
    root: &Path,
    session: &BusinessOsSession,
    mutation: CtoxTaskDeleteMutation,
) -> anyhow::Result<Value> {
    let task_id = resolve_ctox_task_id(root, &mutation.task_id)?;
    anyhow::ensure!(!task_id.is_empty(), "task_id is required");
    anyhow::ensure!(
        session_can_manage_task(root, session, &task_id)?,
        "chef or admin role required"
    );

    let conn = open_store(root)?;
    seed_session_user(&conn, session)?;
    let now = now_ms() as i64;
    if let Some(current) = channels::load_queue_task(root, &task_id)? {
        if !channels::route_status_is_terminal(&current.route_status) {
            let reason = format!("business-os: deleted by {}", session_user_label(session));
            if !channels::transition_business_command_for_task(
                root,
                &task_id,
                "cancelled",
                None,
                Some("cancelled"),
                Some(&reason),
                &reason,
            )? {
                channels::update_queue_task(
                    root,
                    channels::QueueTaskUpdateRequest {
                        message_key: task_id.clone(),
                        route_status: Some("cancelled".to_string()),
                        status_note: Some(reason),
                        ..Default::default()
                    },
                )?;
            }
        }
    }
    let command_id = mutation
        .command_id
        .and_then(non_empty_trimmed)
        .or(queue_projection_command_id(&conn, &task_id)?);
    mark_business_record_deleted(&conn, "ctox_queue_tasks", &task_id, now)?;
    if let Some(command_id) = command_id.as_deref() {
        conn.execute(
            "UPDATE business_commands SET status = 'cancelled', observed_at_ms = ?2 WHERE command_id = ?1",
            params![command_id, now],
        )?;
        mark_business_record_deleted(&conn, "business_commands", command_id, now)?;
    }
    Ok(serde_json::json!({
        "ok": true,
        "task_id": task_id,
        "command_id": command_id,
        "status": "cancelled"
    }))
}

pub(super) fn load_business_command(
    conn: &Connection,
    command_id: &str,
) -> anyhow::Result<BusinessCommand> {
    conn.query_row(
        "SELECT module, command_type, record_id, payload_json, client_context_json
         FROM business_commands
         WHERE command_id = ?1",
        params![command_id],
        |row| {
            let payload_json: String = row.get(3)?;
            let client_context_json: String = row.get(4)?;
            Ok(BusinessCommand {
                origin: CommandOrigin::TrustedLocal,
                id: Some(command_id.to_string()),
                module: row.get(0)?,
                command_type: row.get(1)?,
                record_id: row.get(2)?,
                payload: serde_json::from_str(&payload_json).unwrap_or(Value::Null),
                client_context: serde_json::from_str(&client_context_json).unwrap_or(Value::Null),
            })
        },
    )
    .with_context(|| format!("business command not found: {command_id}"))
}

