    #[test]
    fn app_access_grant_refreshes_catalog_governance_projection() -> anyhow::Result<()> {
        let root = tempfile::tempdir()?;
        let module_id = "grantrefreshapp";
        let collection = "grantrefreshapp_records";
        fs::write(root.path().join("index.html"), "<main></main>\n")?;
        write_minimal_runtime_app_artifacts(root.path(), module_id)?;
        seed_business_user(root.path(), "admin1", "admin")?;

        let outcome = accept_rxdb_business_command(
            root.path(),
            serde_json::json!({
                "id": "cmd-grant-refresh",
                "command_id": "cmd-grant-refresh",
                "module": module_id,
                "command_type": "ctox.app.access.grant",
                "payload": {
                    "module_id": module_id,
                    "subject_type": "role",
                    "subject_id": "admin",
                    "permission": "data.read",
                    "collection": collection,
                    "reason": "reviewed test collection"
                },
                "client_context": {
                    "actor": {"id": "admin1", "role": "admin"}
                }
            }),
        )?;
        assert_eq!(
            outcome.get("status").and_then(Value::as_str),
            Some("completed")
        );

        let catalog =
            load_rxdb_collection_record(root.path(), "business_module_catalog", "module-catalog")?
                .context("module catalog projection is missing")?;
        let grants = catalog
            .pointer("/governance/permission_model/explicit_grants")
            .and_then(Value::as_array)
            .context("catalog governance grants are missing")?;
        assert!(grants.iter().any(|grant| {
            grant.get("grant_id").and_then(Value::as_str)
                == Some("app-access:grantrefreshapp:role:admin:data.read:grantrefreshapp_records")
                && grant.get("active").and_then(Value::as_bool) == Some(true)
        }));
        Ok(())
    }

    fn build_test_app_module_zip(module_id: &str) -> anyhow::Result<Vec<u8>> {
        let mut buffer = Cursor::new(Vec::new());
        {
            let mut zip = zip::ZipWriter::new(&mut buffer);
            let options = zip::write::SimpleFileOptions::default()
                .compression_method(zip::CompressionMethod::Deflated);
            let module_dir = format!("repo/modules/{module_id}");
            zip.add_directory(&module_dir, options)?;
            zip.start_file(format!("{module_dir}/module.json"), options)?;
            zip.write_all(
                serde_json::to_vec_pretty(&serde_json::json!({
                    "id": module_id,
                    "title": "Inventory",
                    "entry": "index.js"
                }))?
                .as_slice(),
            )?;
            zip.start_file(format!("{module_dir}/index.js"), options)?;
            zip.write_all(b"export default {};\n")?;
            zip.finish()?;
        }
        Ok(buffer.into_inner())
    }

    fn seed_test_app_module_zip_upload(
        root: &Path,
        file_id: &str,
        module_id: &str,
    ) -> anyhow::Result<AppStoreInstallRequest> {
        let bytes = build_test_app_module_zip(module_id)?;
        seed_rxdb_chat_attachment(
            root,
            file_id,
            &format!("{module_id}.zip"),
            "application/zip",
            &bytes,
            false,
        )?;
        Ok(AppStoreInstallRequest {
            module_id: module_id.to_owned(),
            download_url: String::new(),
            source_path: String::new(),
            source_kind: "zip".to_owned(),
            repo: String::new(),
            git_ref: String::new(),
            subpath: format!("modules/{module_id}"),
            file_id: file_id.to_owned(),
        })
    }

