    fn assert_policy_denied(
        outcome: &Value,
        permission: &str,
        scope_type: &str,
        scope_id: Option<&str>,
    ) {
        assert_eq!(outcome.get("ok").and_then(Value::as_bool), Some(false));
        assert_eq!(
            outcome.get("status").and_then(Value::as_str),
            Some("failed")
        );
        assert_eq!(
            outcome
                .pointer("/result/policy_decision/permission")
                .and_then(Value::as_str),
            Some(permission)
        );
        assert_eq!(
            outcome
                .pointer("/result/policy_decision/scope_type")
                .and_then(Value::as_str),
            Some(scope_type)
        );
        match scope_id {
            Some(expected) => assert_eq!(
                outcome
                    .pointer("/result/policy_decision/scope_id")
                    .and_then(Value::as_str),
                Some(expected)
            ),
            None => assert_eq!(
                outcome.pointer("/result/policy_decision/scope_id"),
                Some(&Value::Null)
            ),
        }
        assert_eq!(
            outcome
                .pointer("/result/policy_decision/reason_code")
                .and_then(Value::as_str),
            Some("role_or_scope_denied")
        );
    }

    pub(in crate::business_os) fn business_event_payloads(
        conn: &Connection,
        collection: &str,
        record_id: &str,
        command_type: &str,
    ) -> anyhow::Result<Vec<Value>> {
        let mut stmt = conn.prepare(
            "SELECT payload_json
             FROM business_events
             WHERE collection = ?1
               AND record_id = ?2
               AND command_type = ?3
             ORDER BY observed_at_ms ASC, event_id ASC",
        )?;
        let rows = stmt.query_map(params![collection, record_id, command_type], |row| {
            Ok(row.get::<_, String>(0)?)
        })?;
        let mut payloads = Vec::new();
        for row in rows {
            payloads.push(serde_json::from_str(&row?)?);
        }
        Ok(payloads)
    }

    #[test]
    fn push_collection_records_batches_non_command_store_writes_in_one_transaction(
    ) -> anyhow::Result<()> {
        let temp = tempdir()?;
        let root = temp.path();
        reset_push_collection_records_store_transaction_count(root, "customer_opportunities");

        let documents = (0..5)
            .map(|idx| {
                serde_json::json!({
                    "id": format!("opp_{idx}"),
                    "name": format!("Opportunity {idx}"),
                    "updated_at_ms": 1_000 + idx,
                })
            })
            .collect::<Vec<_>>();
        let response = push_collection_records(
            root,
            serde_json::json!({
                "collection": "customer_opportunities",
                "documents": documents,
            }),
        )?;

        assert_eq!(response.get("count").and_then(Value::as_u64), Some(5));
        assert_eq!(
            push_collection_records_store_transaction_count(root, "customer_opportunities"),
            1,
            "non-command push batches must not autocommit once per document"
        );
        let conn = open_store(root)?;
        let rows: i64 = conn.query_row(
            "SELECT COUNT(*)
             FROM business_records
             WHERE collection = 'customer_opportunities'
               AND deleted = 0",
            [],
            |row| row.get(0),
        )?;
        assert_eq!(rows, 5);
        Ok(())
    }

    #[test]
    fn push_collection_records_refreshes_stale_queue_projection_in_same_batch_transaction(
    ) -> anyhow::Result<()> {
        let temp = tempdir()?;
        let root = temp.path();
        let accepted = accept_rxdb_business_command(
            root,
            serde_json::json!({
                "id": "cmd_push_queue_refresh",
                "command_id": "cmd_push_queue_refresh",
                "module": "research",
                "command_type": "business_os.chat.task",
                "record_id": "research",
                "status": "pending_sync",
                "payload": {
                    "title": "Push queue refresh",
                    "instruction": "keep the canonical lease",
                    "prompt": "keep the canonical lease"
                },
                "client_context": {
                    "source": "business-os-chat",
                    "module": "research"
                }
            }),
        )?;
        let task_id = accepted
            .get("task_id")
            .and_then(Value::as_str)
            .context("expected queue task id")?
            .to_string();
        channels::lease_queue_task(root, &task_id, "ctox-service")?;
        reset_push_collection_records_store_transaction_count(root, "ctox_queue_tasks");
        let channel_db_path = crate::paths::core_db(root);
        channels::reset_channel_db_open_count_for_tests(&channel_db_path);
        let documents = (0..25)
            .map(|updated_at_ms| {
                serde_json::json!({
                    "id": task_id,
                    "command_id": "cmd_push_queue_refresh",
                    "status": "queued",
                    "route_status": "pending",
                    "task_status": "queued",
                    "updated_at_ms": updated_at_ms
                })
            })
            .collect::<Vec<_>>();

        let response = push_collection_records(
            root,
            serde_json::json!({
                "collection": "ctox_queue_tasks",
                "documents": documents
            }),
        )?;
        assert_eq!(response.get("count").and_then(Value::as_u64), Some(25));
        assert_eq!(
            push_collection_records_store_transaction_count(root, "ctox_queue_tasks"),
            1,
            "queue refresh must stay inside the one batch store transaction"
        );
        assert_eq!(
            channels::channel_db_open_count_for_tests(&channel_db_path),
            1,
            "one pushed batch must use one canonical queue database read, not one per document"
        );

        let conn = open_store(root)?;
        let payload: Value = serde_json::from_str(&conn.query_row(
            "SELECT payload_json FROM business_records WHERE collection = 'ctox_queue_tasks' AND record_id = ?1",
            params![task_id.as_str()],
            |row| row.get::<_, String>(0),
        )?)?;
        assert_eq!(
            payload.get("route_status").and_then(Value::as_str),
            Some("leased")
        );
        assert_eq!(
            payload.get("status").and_then(Value::as_str),
            Some("running")
        );
        assert_eq!(
            payload.get("task_status").and_then(Value::as_str),
            Some("running")
        );
        Ok(())
    }

    #[test]
    fn module_governance_projection_includes_permission_model_and_grants() -> anyhow::Result<()> {
        let temp = tempdir()?;
        let root = temp.path();
        let conn = open_store(root)?;
        let now = now_ms() as i64;
        conn.execute(
            "INSERT INTO business_module_acl
                (module_id, user_id, role, active, created_at_ms, updated_at_ms)
             VALUES ('inventory', 'app-owner', 'founder', 1, ?1, ?1)",
            params![now],
        )?;
        conn.execute(
            "INSERT INTO business_permission_grants
                (grant_id, subject_type, subject_id, permission, scope_type, scope_id,
                 active, reason, created_by, created_at_ms, updated_at_ms)
             VALUES (?1, 'user', 'viewer', ?2, 'module', 'inventory', 1,
                 'approval delegate', 'tester', ?3, ?3)",
            params![
                "grant_viewer_inventory_external_approve",
                BusinessOsPermission::ExternalApprove.as_str(),
                now
            ],
        )?;
        conn.execute(
            "INSERT INTO business_permission_grants
                (grant_id, subject_type, subject_id, permission, scope_type, scope_id,
                 active, reason, created_by, created_at_ms, updated_at_ms)
             VALUES ('migration.sync.inventory.viewer', 'role', 'user', ?1,
                 'collection', 'inventory_records', 1, 'legacy compatibility',
                 'migration', ?2, ?2)",
            params![BusinessOsPermission::DataRead.as_str(), now],
        )?;
        drop(conn);

        let governance = module_governance_map(root, &chef_session())?;
        let model = governance
            .get("permission_model")
            .expect("governance projects permission model");
        assert_eq!(model.get("version").and_then(Value::as_i64), Some(1));
        assert_eq!(
            model.get("deny_supported").and_then(Value::as_bool),
            Some(false)
        );
        let founder_assigned = model
            .pointer("/role_defaults/founder/assigned_module")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        assert!(founder_assigned.iter().any(|permission| {
            permission.as_str() == Some(BusinessOsPermission::AppsView.as_str())
        }));
        assert!(founder_assigned.iter().any(|permission| {
            permission.as_str() == Some(BusinessOsPermission::AppsModify.as_str())
        }));

        let owner_permissions = model
            .pointer("/module_assignments/inventory/app-owner")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        assert!(owner_permissions.iter().any(|permission| {
            permission.as_str() == Some(BusinessOsPermission::AppsView.as_str())
        }));
        assert!(owner_permissions.iter().any(|permission| {
            permission.as_str() == Some(BusinessOsPermission::AppsRelease.as_str())
        }));

        let explicit_grants = model
            .get("explicit_grants")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        assert!(explicit_grants.iter().any(|grant| {
            grant.get("grant_id").and_then(Value::as_str)
                == Some("grant_viewer_inventory_external_approve")
                && grant.get("permission").and_then(Value::as_str)
                    == Some(BusinessOsPermission::ExternalApprove.as_str())
                && grant.get("scope_id").and_then(Value::as_str) == Some("inventory")
        }));
        assert!(!explicit_grants.iter().any(|grant| {
            grant.get("grant_id").and_then(Value::as_str) == Some("migration.sync.inventory.viewer")
        }));
        Ok(())
    }

