    #[test]
    fn app_store_install_uninstall_allows_explicit_module_grants() -> anyhow::Result<()> {
        let temp = tempdir()?;
        let root = temp.path();
        seed_test_business_os_app_root(root)?;
        seed_business_user(root, "viewer", "user")?;
        seed_business_user(root, "ungranted-viewer", "user")?;
        seed_permission_grant(
            root,
            "grant_viewer_install_inventory",
            "user",
            "viewer",
            BusinessOsPermission::AppsInstall,
            "module",
            "inventory",
        )?;
        seed_permission_grant(
            root,
            "grant_viewer_uninstall_inventory",
            "user",
            "viewer",
            BusinessOsPermission::AppsUninstall,
            "module",
            "inventory",
        )?;
        let request = seed_test_app_module_zip_upload(root, "granted_inventory_zip", "inventory")?;
        let installed_app_root = resolve_business_os_installed_app_root(root);
        let granted_session = test_session("viewer", "user");
        let ungranted_session = test_session("ungranted-viewer", "user");

        assert!(
            module_policy_decision(
                root,
                &granted_session,
                BusinessOsPermission::AppsInstall,
                "inventory",
            )?
            .allowed
        );
        let granted_error =
            install_app_module(root, &installed_app_root, &granted_session, request.clone())
                .expect_err("the explicit install grant must reach the later trust gate");
        assert_eq!(
            granted_error.to_string(),
            "untrusted third-party apps cannot run same-origin; install a CTOX first-party source or wait for the sandbox runtime"
        );

        assert!(
            !module_policy_decision(
                root,
                &ungranted_session,
                BusinessOsPermission::AppsInstall,
                "inventory",
            )?
            .allowed
        );
        let ungranted_error =
            install_app_module(root, &installed_app_root, &ungranted_session, request)
                .expect_err("an ungranted user must be stopped by the install policy check");
        assert_eq!(
            ungranted_error.to_string(),
            "chef or admin role required to install modules"
        );

        let installed_manifest = installed_app_root
            .join("installed-modules")
            .join("inventory")
            .join("module.json");
        write_test_manifest(
            installed_manifest
                .parent()
                .context("installed module directory")?,
            "inventory",
        )?;
        seed_module_founder_acl(root, "inventory", "viewer")?;
        let now = now_ms() as i64;
        let conn = open_store(root)?;
        conn.execute(
            "INSERT INTO business_module_releases
                (version_id, module_id, version, status, manifest_json, snapshot_json,
                 created_by, created_at_ms, notes)
             VALUES ('release_inventory_uninstall', 'inventory', 1, 'released', '{}', '{}',
                 'viewer', ?1, 'uninstall cleanup')",
            params![now],
        )?;
        conn.execute(
            "INSERT INTO business_module_versions
                (version_id, module_id, seq, origin, label, bundle_sha256, files_json,
                 sealed, created_by, created_at_ms, updated_at_ms)
             VALUES ('version_inventory_uninstall', 'inventory', 1, 'install', 'Installed',
                 'sha-inventory-uninstall', '[]', 1, 'viewer', ?1, ?1)",
            params![now],
        )?;
        drop(conn);
        let uninstall = uninstall_app_module(
            root,
            &installed_app_root,
            &granted_session,
            AppStoreUninstallRequest {
                module_id: "inventory".to_owned(),
            },
        )?;
        assert_eq!(uninstall.get("ok").and_then(Value::as_bool), Some(true));
        assert_eq!(
            uninstall.get("uninstalled").and_then(Value::as_bool),
            Some(true)
        );
        assert!(!installed_manifest.exists());
        let conn = open_store(root)?;
        let remaining: (i64, i64, i64, i64) = conn.query_row(
            "SELECT
                (SELECT COUNT(*) FROM business_module_acl WHERE module_id = 'inventory'),
                (SELECT COUNT(*) FROM business_permission_grants
                    WHERE scope_type = 'module' AND scope_id = 'inventory'),
                (SELECT COUNT(*) FROM business_module_releases WHERE module_id = 'inventory'),
                (SELECT COUNT(*) FROM business_module_versions WHERE module_id = 'inventory')",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )?;
        assert_eq!(remaining, (0, 0, 0, 0));
        Ok(())
    }

