    #[test]
    fn business_os_why_command_explains_private_app_policy_and_data_access() -> anyhow::Result<()> {
        let temp = tempdir()?;
        let root = temp.path();
        seed_test_business_os_app_root(root)?;
        fs::create_dir_all(root.join("runtime"))?;
        let installed_app_root = resolve_business_os_installed_app_root(root);
        write_installed_inventory_module(&installed_app_root, "0.9.0")?;
        seed_business_user(root, "global_admin", "admin")?;
        seed_business_user(root, "qa", "user")?;
        seed_permission_grant(
            root,
            "grant_qa_inventory_view",
            "user",
            "qa",
            BusinessOsPermission::AppsView,
            "module",
            "inventory",
        )?;
        seed_permission_grant(
            root,
            "grant_team_inventory_read",
            "role",
            "user",
            BusinessOsPermission::DataRead,
            "collection",
            "inventory_items",
        )?;

        let admin = accept_rxdb_business_command(
            root,
            serde_json::json!({
                "id": "cmd_why_admin_private_inventory",
                "module": "ctox",
                "type": "ctox.business_os.why",
                "payload": {
                    "module_id": "inventory",
                    "prompt": "DO_NOT_LEAK_PROMPT",
                    "token": "DO_NOT_LEAK_TOKEN"
                },
                "client_context": {
                    "actor": {
                        "id": "global_admin",
                        "display_name": "Global Admin"
                    },
                    "selected_text": "DO_NOT_LEAK_SELECTED_TEXT"
                }
            }),
        )?;
        assert_eq!(
            admin.get("status").and_then(Value::as_str),
            Some("completed")
        );
        assert_eq!(
            admin
                .pointer("/result/decisions/visibility/allowed")
                .and_then(Value::as_bool),
            Some(false),
            "admin authority may manage a private 0.x app but must not make it team-visible"
        );
        assert_eq!(
            admin
                .pointer("/result/decisions/open/allowed")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            admin
                .pointer("/result/decisions/modify/allowed")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            admin
                .pointer("/result/decisions/visibility/source")
                .and_then(Value::as_str),
            Some("lifecycle_non_public")
        );
        let admin_json = serde_json::to_string(&admin)?;
        assert!(!admin_json.contains("DO_NOT_LEAK"));
        let conn = open_store(root)?;
        let stored_admin = outbound_load_required(
            &conn,
            "business_commands",
            "cmd_why_admin_private_inventory",
            "command",
        )?;
        let stored_admin_json = serde_json::to_string(&stored_admin)?;
        assert!(
            !stored_admin_json.contains("DO_NOT_LEAK"),
            "why command projections must persist a sanitized payload and context"
        );
        drop(conn);

        let qa = accept_rxdb_business_command(
            root,
            serde_json::json!({
                "id": "cmd_why_qa_private_inventory",
                "module": "ctox",
                "type": "ctox.business_os.why",
                "payload": {
                    "module_id": "inventory"
                },
                "client_context": {
                    "actor": {
                        "id": "qa",
                        "display_name": "QA"
                    }
                }
            }),
        )?;
        assert_eq!(
            qa.pointer("/result/decisions/visibility/allowed")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            qa.pointer("/result/decisions/visibility/source")
                .and_then(Value::as_str),
            Some("explicit_app_view_or_app_responsibility")
        );
        assert_eq!(
            qa.pointer("/result/decisions/modify/allowed")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            qa.pointer("/result/data_access/areas/0/collection")
                .and_then(Value::as_str),
            Some("inventory_items")
        );
        assert_eq!(
            qa.pointer("/result/data_access/areas/0/read_decision/allowed")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            qa.pointer("/result/data_access/areas/0/read_decision/source")
                .and_then(Value::as_str),
            Some("collection_policy")
        );
        assert_eq!(
            qa.pointer("/result/data_access/areas/0/write_decision/allowed")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            qa.pointer("/result/data_access/areas/0/write_decision/source")
                .and_then(Value::as_str),
            Some("denied_collection_and_module_policy")
        );
        Ok(())
    }

    #[test]
    fn ctox_secret_put_keeps_value_out_of_command_record_and_lists_metadata() -> anyhow::Result<()>
    {
        let temp = tempdir()?;
        let root = temp.path();
        seed_test_business_os_app_root(root)?;
        fs::create_dir_all(root.join("runtime"))?;
        seed_business_user(root, "global_admin", "admin")?;
        seed_business_user(root, "qa", "user")?;

        // Admin stores a credential. The plaintext value must never appear in
        // the command outcome.
        let put = accept_rxdb_business_command(
            root,
            serde_json::json!({
                "id": "cmd_secret_put",
                "module": "credentials",
                "type": "ctox.secret.put",
                "payload": { "name": "OPENAI_API_KEY", "value": "DO_NOT_LEAK_SECRET_VALUE" },
                "client_context": {
                    "actor": { "id": "global_admin", "display_name": "Global Admin" }
                }
            }),
        )?;
        assert_eq!(put.get("status").and_then(Value::as_str), Some("completed"));
        assert!(
            !serde_json::to_string(&put)?.contains("DO_NOT_LEAK_SECRET_VALUE"),
            "secret value leaked into the command outcome"
        );

        // The value lands (encrypted) in the secret store and is retrievable
        // only there — proving the write actually happened.
        assert_eq!(
            crate::secrets::read_secret_value(
                root,
                crate::secrets::credential_scope(),
                "OPENAI_API_KEY"
            )?,
            "DO_NOT_LEAK_SECRET_VALUE"
        );

        // Guard: the persisted business_commands projection must be redacted.
        let conn = open_store(root)?;
        let stored =
            outbound_load_required(&conn, "business_commands", "cmd_secret_put", "command")?;
        drop(conn);
        assert!(
            !serde_json::to_string(&stored)?.contains("DO_NOT_LEAK_SECRET_VALUE"),
            "secret value leaked into the persisted business_commands record"
        );

        // Listing returns metadata only; the catalog marks the key as set and
        // no value appears anywhere in the outcome.
        let list = accept_rxdb_business_command(
            root,
            serde_json::json!({
                "id": "cmd_secret_list",
                "module": "credentials",
                "type": "ctox.secret.list",
                "payload": {},
                "client_context": {
                    "actor": { "id": "global_admin", "display_name": "Global Admin" }
                }
            }),
        )?;
        assert_eq!(
            list.get("status").and_then(Value::as_str),
            Some("completed")
        );
        let openai_set = list
            .pointer("/result/catalog")
            .and_then(Value::as_array)
            .map(|catalog| {
                catalog.iter().any(|entry| {
                    entry.get("name").and_then(Value::as_str) == Some("OPENAI_API_KEY")
                        && entry.get("is_set").and_then(Value::as_bool) == Some(true)
                })
            });
        assert_eq!(openai_set, Some(true));
        assert!(!serde_json::to_string(&list)?.contains("DO_NOT_LEAK_SECRET_VALUE"));

        // A non-admin (user role) is denied server-side, regardless of any UI.
        // The denied command's persisted record must also be redacted — the
        // rejection path persists the command we hand it.
        let denied = accept_rxdb_business_command(
            root,
            serde_json::json!({
                "id": "cmd_secret_put_denied",
                "module": "credentials",
                "type": "ctox.secret.put",
                "payload": { "name": "ANTHROPIC_API_KEY", "value": "DENIED_LEAK_VALUE" },
                "client_context": { "actor": { "id": "qa", "display_name": "QA" } }
            }),
        )?;
        assert_eq!(denied.get("status").and_then(Value::as_str), Some("failed"));
        assert!(!serde_json::to_string(&denied)?.contains("DENIED_LEAK_VALUE"));
        assert!(
            crate::secrets::list_secret_records(root, Some(crate::secrets::credential_scope()))?
                .iter()
                .all(|record| record.secret_name != "ANTHROPIC_API_KEY"),
            "denied put must not write a credential"
        );
        let conn = open_store(root)?;
        let stored_denied = outbound_load_required(
            &conn,
            "business_commands",
            "cmd_secret_put_denied",
            "command",
        )?;
        drop(conn);
        assert!(
            !serde_json::to_string(&stored_denied)?.contains("DENIED_LEAK_VALUE"),
            "denied put leaked the secret value into the persisted record"
        );

        // Delete removes the credential.
        let delete = accept_rxdb_business_command(
            root,
            serde_json::json!({
                "id": "cmd_secret_delete",
                "module": "credentials",
                "type": "ctox.secret.delete",
                "payload": { "name": "OPENAI_API_KEY" },
                "client_context": {
                    "actor": { "id": "global_admin", "display_name": "Global Admin" }
                }
            }),
        )?;
        assert_eq!(
            delete.get("status").and_then(Value::as_str),
            Some("completed")
        );
        assert!(!crate::secrets::secret_exists(
            root,
            crate::secrets::credential_scope(),
            "OPENAI_API_KEY"
        )?);
        Ok(())
    }

